from pathlib import Path
import json,re,base64
from playwright.sync_api import sync_playwright
ROOT=Path(__file__).resolve().parents[1]
CSS=(ROOT/'source/base.css').read_text()
IDS=['puffer','chicken','bubble_fish','electric_sheep','magnet_crab','duck','rabbit','cactus','shell_turtle','crow']
NAMES=['充气球','炸弹母鸡','泡泡鱼','触电羊','磁铁蟹','倒霉鸭','锻造兔','仙人掌','脱壳乌龟','乌鸦']
SKILLS=[['充气','吸收'],['乱跑','大炸弹'],['吸附泡泡','八方泡泡'],['转向墙壁','放置羊毛'],['磁力墙','铁钉弹射'],['调整雷表','避雷针'],['现场锻造','淬火'],['撒刺','换地方生长'],['躲进壳中','旋转龟壳'],['交换位置','储存羽毛']]
IMAGES=[]
for ident in IDS:
 p=Path('/workspace/balls/assets')/('r02' if ident in ['duck','rabbit'] else 'r04')/'characters'/ident/('default.png' if ident in ['duck','rabbit'] else 'idle.png')
 IMAGES.append('data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode())
fixtures_path=ROOT.parent/'fixtures.json'
if not fixtures_path.exists():fixtures_path=ROOT/'source/fixtures.json'
samples=json.loads(fixtures_path.read_text())['people']
extra='''button:focus-visible,select:focus-visible{outline:3px solid #d49560;outline-offset:3px}button{cursor:pointer}.gallerybar{display:flex;justify-content:space-between;align-items:center}.gallerybar .controls{display:flex;gap:10px;align-items:center}.gallerybar button{height:48px;min-width:48px}.gallerybar select{height:48px;width:360px;font:inherit;color:#345149;background:#f8f9ef;border:1px solid #b1c3ab;border-radius:5px;padding:0 12px}.gallery{height:260px;display:grid;grid-template-columns:1fr 1fr 1.7fr 1fr 1fr;gap:16px;align-items:center;margin:16px 0 20px}.gallery button{padding:0;flex-direction:column;border:1px solid #d0d9c6;color:#50685a;font-size:17px;height:190px;opacity:.72}.gallery button.selected{height:255px;border:3px solid #7b9b7f;background:#e7f0df;opacity:1}.gallery .sprite{width:125px;height:125px}.gallery .selected .sprite{width:205px;height:205px}.gallery button.selected .caption{font-size:20px;font-weight:700}.gallery .caption{position:relative;z-index:1}.lower{display:grid;grid-template-columns:1.35fr 1fr;gap:24px;height:360px}.attr table th,.attr table td{padding:6px 5px}.attr .sectionhead{margin:0 0 7px}.attr .explain{padding:6px 12px;font-size:15px;min-height:48px}.lower .skills>div{padding:8px 12px}.lower .hint{margin-top:6px}.lower .divider{margin:10px 0!important}.overlay{display:none;position:absolute;inset:92px 0 46px;background:#29473f66;z-index:8;align-items:center;justify-content:center}.overlay.open{display:flex}.modal{width:900px;padding:30px;background:#fcfaf2;border:3px solid #74927c;border-radius:12px;box-shadow:8px 8px 0 #637f634d}.modal h2{margin:0}.modal p{font-size:19px;line-height:1.9}.badge{font-size:14px;background:#e6eee0;padding:6px 12px;border-radius:5px}.childnote{color:#8a6851;font-size:14px}.emptycard{height:190px;display:flex;align-items:center;justify-content:center;color:#a3b19c;font-size:18px}'''
header='<header><div class="brand">BALLS <span style="font-size:15px;letter-spacing:1px;color:#94a08d">20固定示例 + 本机孵出</span></div><nav>'+''.join(f'<button data-nav="{id}" class="{"on" if id=="storage" else ""}">{name}</button>' for id,name in [('arena','竞技场'),('story','主线'),('storage','仓库'),('hatch','孵蛋')])+'</nav><span class="round">横屏 · 交互演示</span></header>'
content='''<div style="padding:22px 34px"><div class="gallerybar"><h2 style="margin:0">精灵画廊</h2><div class="controls"><button class="subaction" id="prev" aria-label="上一个体">‹</button><select id="individual" aria-label="选择仓库个体"></select><button class="subaction" id="next" aria-label="下一个体">›</button><span class="badge" id="counter">05 / 20</span></div></div><div class="gallery" id="gallery"></div><div class="lower"><section class="pane attr"><div class="sectionhead"><b>属性资料</b><button class="subaction explain" id="explain">属性说明　ⓘ</button></div><div class="sectionhead"><b>六维属性</b><span>全部来源 · 始终展开</span></div><table><thead><tr><th>属性</th><th>种族基础</th><th>先天</th><th>后天</th><th>最终</th></tr></thead><tbody id="statrows"></tbody></table></section><section class="pane"><div class="sectionhead"><b>特性</b><span>1 / 3</span></div><div class="trait" id="trait">✦ 特性一 <small>待设计</small></div><div class="hint" id="othertraits">其他特性：特性二、特性三 · 待设计</div><div class="divider"></div><div class="sectionhead"><b>已拥有技能</b><span>2 / 5</span></div><div class="skills" id="skills"></div><div class="hint" id="otherskills"></div></section></div></div><div class="overlay" id="info" role="dialog" aria-modal="true" aria-label="属性说明"><div class="modal"><div class="sectionhead"><h2>属性资料说明</h2><button class="subaction" id="close-info">关闭　×</button></div><p>六项属性均保留四种来源：种族基础、先天、后天、最终。<br>种族基础和最终数值尚未设计，当前显示“待定”。<br>先天值不是最终值，后天值为0；不虚构计算公式。</p><p>默认展示的泡泡鱼♀两个技能+3 / +3是人工评审样例，<br>不是代码固定示例的默认技能等级。鱼♀和羊♂为人工3/3，其余固定个体依代码公式展示。</p><div class="childnote">网页可接收孵蛋演示个体，仅存在当前页面内存；不写入游戏存档。</div></div></div>'''
footer='<footer><span id="status">泡泡鱼♀ Lv.0 · +3 / +3 人工评审样例</span><span>完整属性默认展开 · 非游戏实时数据 · 未接入</span></footer>'
js='''const NAMES=__NAMES__,SKILLS=__SKILLS__,IMAGES=__IMAGES__,samples=__SAMPLES__;let selected=4;const statNames=['生命','攻击','防御','速度','重量','大小'];let lastFocus=null;
function label(c){return `${NAMES[c.species]} ${c.sex===0?'♀':'♂'} Lv.${c.level}${c.number?' #'+c.number:' · 固定示例'}`}
function fullSkill(c,id){return id<2?SKILLS[c.species][id]:`技能${['一','二','三','四','五'][id]}（待设计）`}
function selectIndex(i){selected=Math.max(0,Math.min(samples.length-1,i));render()}
function render(){const c=samples[selected];document.getElementById('individual').innerHTML=samples.map((x,i)=>`<option value="${i}" ${i===selected?'selected':''}>${label(x)}</option>`).join('');document.getElementById('counter').textContent=`${String(selected+1).padStart(2,'0')} / ${samples.length}`;
 document.getElementById('gallery').innerHTML=Array.from({length:5},(_,k)=>{const i=selected+k-2;if(i<0||i>=samples.length)return '<div class="emptycard">·</div>';const x=samples[i];return `<button class="hero ${i===selected?'selected':''}" data-select="${i}" aria-label="选择${label(x)}"><img class="sprite" src="${IMAGES[x.species]}" alt=""><div class="caption">${label(x).replace(' · 固定示例','')}</div></button>`}).join('');
 document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>selectIndex(Number(b.dataset.select)));document.getElementById('prev').disabled=selected===0;document.getElementById('next').disabled=selected===samples.length-1;
 document.getElementById('statrows').innerHTML=statNames.map((n,i)=>`<tr><th>${n}</th><td class="muted">待定</td><td><b>${c.innate[i]}</b></td><td>${c.training[i]}</td><td class="muted">待定</td></tr>`).join('');
 const traitMatch=String(c.trait).match(/特性([一二三])/);const current=traitMatch?traitMatch[1]:'一';document.getElementById('trait').innerHTML=`✦ 特性${current} <small>待设计</small>`;document.getElementById('othertraits').textContent='其他特性：'+['一','二','三'].filter(n=>n!==current).map(n=>'特性'+n).join('、')+' · 待设计';
 document.getElementById('skills').innerHTML=c.skills.map((id,k)=>`<div><i>${k===0?'◉':'✣'}</i><b>${fullSkill(c,id)}</b><strong>+${c.ranks[k]}</strong></div>`).join('');document.getElementById('otherskills').textContent='其他技能：'+[0,1,2,3,4].filter(id=>!c.skills.includes(id)).map(id=>fullSkill(c,id)).join(' / ');
 document.getElementById('status').textContent=label(c)+(c.number?' · 人工孵出示例，仅当前页面内存':(c.species===2&&c.sex===0)||(c.species===3&&c.sex===1)?' · +3 / +3 人工评审样例':' · 固定示例按当前代码公式展示');}
function closeInfo(){document.getElementById('info').classList.remove('open');if(lastFocus)lastFocus.focus()}
document.getElementById('prev').onclick=()=>selectIndex(selected-1);document.getElementById('next').onclick=()=>selectIndex(selected+1);document.getElementById('individual').onchange=e=>selectIndex(Number(e.target.value));document.getElementById('explain').onclick=()=>{lastFocus=document.activeElement;document.getElementById('info').classList.add('open');document.getElementById('close-info').focus()};document.getElementById('close-info').onclick=closeInfo;document.getElementById('info').onclick=e=>{if(e.target.id==='info')closeInfo()};document.addEventListener('keydown',e=>{if(e.key==='Escape')closeInfo()});
document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{if(b.dataset.nav==='storage'){render();return}if(window.parent!==window)window.parent.postMessage({type:'r06-nav',page:b.dataset.nav},location.origin);else document.getElementById('status').textContent='请在整合评审页切换至'+b.textContent+'；独立页只演示仓库。'});
function acceptChild(raw){if(!raw||typeof raw!=='object')return false;const c=JSON.parse(JSON.stringify(raw));if(!Number.isInteger(c.species)||c.species<0||c.species>=10||![0,1].includes(c.sex)||!Number.isInteger(c.level)||c.level<0||c.level>100)return false;for(const key of ['innate','training'])if(!Array.isArray(c[key])||c[key].length!==6||!c[key].every(x=>Number.isInteger(x)&&x>=0))return false;if(!Array.isArray(c.skills)||c.skills.length!==2||c.skills.some(x=>!Number.isInteger(x)||x<0||x>4)||c.skills[0]===c.skills[1]||!Array.isArray(c.ranks)||c.ranks.length!==2||c.ranks.some(x=>!Number.isInteger(x)||x<1||x>10))return false;if(c.innate.some(x=>x<1||x>50)||c.training.some(x=>x>100)||c.training.reduce((a,b)=>a+b,0)>200)return false;c.number=21;c.trait=typeof c.trait==='string'?c.trait:'特性一（待设计）';c.demo=true;const old=samples.findIndex(x=>x.number===21);if(old>=0){samples[old]=c;selected=old}else{samples.push(c);selected=samples.length-1}render();return true}
window.addEventListener('message',event=>{if(event.source!==window.parent||event.origin!==location.origin)return;if(event.data?.type==='r06-demo-child')acceptChild(event.data.child)});window.r06Storage={acceptChild,selectIndex,getState:()=>({selected,count:samples.length,current:samples[selected]})};render();'''
for key,val in [('NAMES',NAMES),('SKILLS',SKILLS),('IMAGES',IMAGES),('SAMPLES',samples)]:js=js.replace('__'+key+'__',json.dumps(val,ensure_ascii=False))
html='<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=1600"><title>仓库 · 完整资料默认</title><style>'+CSS+extra+'</style><body><main>'+header+content+footer+'</main><script>'+js+'</script></body></html>'
(ROOT/'source.html').write_text(html)
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);page=b.new_page(viewport={'width':1600,'height':900},device_scale_factor=1);page.set_content(html);page.screenshot(path=str(ROOT/'main.png'))
 page.locator('#explain').click();page.screenshot(path=str(ROOT/'info.png'));page.locator('#close-info').click()
 page.locator('#next').click();page.screenshot(path=str(ROOT/'individual.png'))
 child=json.loads((ROOT/'source/demo_child.json').read_text());page.evaluate('(c)=>window.r06Storage.acceptChild(c)',child);page.screenshot(path=str(ROOT/'demo_child.png'))
 b.close()
review={'id':'storage','title':'仓库','image':'main.png','prototype':'source.html','source':'source.html','status':'按已选D整理；完整资料默认展开，非游戏接入','canvas':[1600,900],'detail_images':[{'image':'info.png','title':'属性说明'},{'image':'individual.png','title':'切换个体'},{'image':'demo_child.png','title':'演示后代 · 仅内存'}],'confirmed':['横向逐个体画廊','完整6×4属性默认常驻','不保留折叠主状态','20固定示例与本机孵出个体分清'],'notes':['母鱼+3/+3人工UI样例，统一fixtures鱼♀与羊♂使用人工3/3，其余按game_pages公式','基础/最终待定，不增加培养或出战','后代仅网页内存示例，无真实孵化/存档写入','固定1600×900，本轮不做手机适配']}
(ROOT/'review.json').write_text(json.dumps(review,ensure_ascii=False,indent=2)+'\n')
